True def transform(grid):
    h, w = len(grid), len(grid[0])
    cr = next(r for r, row in enumerate(grid) if all(v == 3 for v in row))
    cc = next(c for c in range(w) if all(grid[r][c] == 3 for r in range(h)))
    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if r == cr or c == cc:
                out[r][c] = 3
            elif max(abs(r - cr), abs(c - cc)) % 2 == 0:
                out[r][c] = 4
    return out
